import json, re
d = json.load(open("$SP/schema_full.json".replace("$SP", "/tmp/claude-0/-home-user-guidebook/e124fa82-8e34-508e-805f-fe29e0f1c1c9/scratchpad")))
tables = {x["name"] for x in d if x["type"]=="table"}
views = [x for x in d if x["type"]=="view"]
# For each view, find which tables/views it references via FROM/JOIN
name_re = lambda n: re.compile(r'(?:FROM|JOIN)\s+"?%s"?\b' % re.escape(n), re.I)
view_refs = {}
for v in views:
    refs = set()
    for t in tables:
        if name_re(t).search(v["sql"]):
            refs.add(t)
    view_refs[v["name"]] = sorted(refs)
for vn, refs in view_refs.items():
    print(vn, "->", refs)
